import { useState } from "react";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { Send } from "lucide-react";

export function ChatInput({
    onSendMessage,
    disabled = false,
    placeholder = "Type your message..."
}) {
    const [message, setMessage] = useState("");

    const handleSubmit = (e) => {
        e.preventDefault();
        if (message.trim() && !disabled) {
            onSendMessage(message.trim());
            setMessage("");
        }
    };

    const handleKeyPress = (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSubmit(e);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="flex gap-2 p-4 border-t bg-gradient-to-r from-slate-100 to-gray-100">
            <Input
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                onKeyPress={handleKeyPress}
                placeholder={placeholder}
                disabled={disabled}
                className="flex-1 bg-white border-2 border-slate-200 focus:border-blue-400 rounded-full px-4"
            />
            <Button
                type="submit"
                disabled={!message.trim() || disabled}
                size="icon"
                className="bg-gradient-to-r from-blue-600 to-slate-700 hover:from-blue-700 hover:to-slate-800 rounded-full"
            >
                <Send className="w-4 h-4" />
            </Button>
        </form>
    );
}
